package main

import "fmt"

type Node struct {
	Value int
	Next  *Node
}

// ReverseLinkedList invierte una lista enlazada
func ReverseLinkedList(head *Node) *Node {
	var prev *Node
	current := head

	for current != nil {
		// Guardar el siguiente nodo antes de cambiar el puntero
		next := current.Next

		// Cambiar el puntero del nodo actual
		current.Next = prev

		// Mover prev y current un paso adelante
		prev = current
		current = next
	}

	return prev // El nuevo head es el último nodo
}

// Función auxiliar para imprimir la lista
func PrintList(head *Node) {
	for head != nil {
		fmt.Print(head.Value, " -> ")
		head = head.Next
	}
	fmt.Println("nil")
}

func main() {
	// Crear lista: 1 -> 2 -> 3 -> 4 -> nil
	head := &Node{Value: 1, Next: &Node{Value: 2, Next: &Node{Value: 3, Next: &Node{Value: 4}}}}

	fmt.Print("Original: ")
	PrintList(head)

	head = ReverseLinkedList(head)

	fmt.Print("Invertida: ")
	PrintList(head)
}
```

**Salida:**
```
Original: 1 -> 2 -> 3 -> 4 -> nil
Invertida: 4 -> 3 -> 2 -> 1 -> nil
```

**Cómo funciona:**
1. Usamos tres punteros: `prev` (nodo anterior), `current` (nodo actual), `next` (siguiente nodo)
2. En cada iteración guardamos el siguiente nodo antes de modificar el puntero
3. Invertimos el puntero del nodo actual para que apunte al anterior
4. Avanzamos `prev` y `current` una posición
5. Cuando terminamos, `prev` apunta al nuevo head

**Complejidad:**
- Tiempo: O(n) - visitamos cada nodo una vez
- Espacio: O(1) - solo usamos tres variables auxiliares

